INSERT INTO zoho_import.notes ("note_record_id", "person_type", "person_record_id", "person_name", "note_title", "note_content", "note_owner", "created_by", "created_time", "modified_time") VALUES
  ('zcrm_1579374000062305018', 'contact', 'zcrm_1579374000060961101', 'Brad Storz', NULL, 'Brad called in for assistance in understanding his preventative care benefits.   I took the time to explain them and sent him all preventative care templates.  I also expressed the the importance of a welcome call- I sent him a scheduler.  Brad was thrilled to have prompt answers to his questions. - KC', 'Kelly Cheever', 'Kelly Cheever', '2021-01-15 11:52:45', '2021-01-15 11:52:45'),
  ('zcrm_1579374000062294031', 'contact', 'zcrm_1579374000044842469', 'Paula Fowke', NULL, 'Because of email issues w/CRM the email requesting cancellation was sent out of outlook.  Repeated attempts shown in the emil', 'Patti Baron', 'Patti Baron', '2021-01-15 11:48:37', '2021-01-15 11:48:37'),
  ('zcrm_1579374000062294026', 'contact', 'zcrm_1579374000001709173', 'Leslie McDougall', NULL, 'Member called and I got a Bettirgram letting me know that she had cancelled with LHS  and us and was charged.  She had called in 1/5 and email was wrong.  I will refund her and cancel.', 'Patti Baron', 'Patti Baron', '2021-01-15 11:36:49', '2021-01-15 11:36:49'),
  ('zcrm_1579374000062310008', 'contact', 'zcrm_1579374000032122001', 'Eileen Fagan', 'Questions about Direct Plan', '-Spoke with member regarding DPC Plan.  Has several more questions before moving forward:
